//! Pre-commit hook management: install, uninstall, read, check.
//!
//! ## Sub-modules
//! - [`types`]: PrecommitConfig, HOOK_NAME, hooks_dir.

pub mod types;

pub use types::PrecommitConfig;

use sisyphus_tools_core::{ToolError, ToolResult};
use std::path::Path;
use types::{hooks_dir, HOOK_NAME};

/// Generate the pre-commit hook script content based on configuration.
fn generate_hook_script(cfg: &PrecommitConfig) -> String {
    let mut lines: Vec<String> = vec![
        "#!/bin/sh".into(),
        "# Sisyphus pre-commit hook — auto-generated by `sisyphus precommit install`".into(),
        "set -e".into(),
        String::new(),
    ];

    match cfg.backend.as_str() {
        "rust" => gen_rust_hook(cfg, &mut lines),
        "node" | "ts" | "js" => gen_node_hook(cfg, &mut lines),
        "python" | "py" => gen_python_hook(cfg, &mut lines),
        "go" | "golang" => gen_go_hook(cfg, &mut lines),
        "java" | "maven" | "gradle" => gen_java_hook(cfg, &mut lines),
        "fe" | "frontend" | "css" | "html" => gen_frontend_hook(cfg, &mut lines),
        _ => gen_rust_hook(cfg, &mut lines),
    }

    lines.push("echo \"✅ All pre-commit checks passed.\"".into());
    lines.push(String::new());
    lines.join("\n")
}

fn gen_rust_hook(cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    if cfg.check_fmt {
        lines.push("echo \"🔍 Checking formatting with cargo fmt...\"".into());
        lines.push(
            "cargo fmt --check || { echo \"❌ Formatting check failed. Run 'cargo fmt' to fix.\"; exit 1; }"
                .into(),
        );
        lines.push(String::new());
    }

    if cfg.check_lint {
        let cmd = if cfg.lint_deny_warnings {
            "cargo clippy -- -D warnings"
        } else {
            "cargo clippy"
        };
        lines.push("echo \"🔍 Running cargo clippy...\"".into());
        lines.push(format!(
            "{cmd} || {{ echo \"❌ Clippy found issues.\"; exit 1; }}"
        ));
        lines.push(String::new());
    }
}

fn gen_node_hook(_cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    lines.push("echo \"🔍 Checking formatting with prettier...\"".into());
    lines.push(
        "if command -v prettier >/dev/null 2>&1; then prettier --check . || { echo \"❌ Formatting issues found. Run 'prettier --write .' to fix.\"; exit 1; }; else echo \"  ⚠ prettier not installed, skipping format check\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push("echo \"🔍 Running eslint...\"".into());
    lines.push(
        "if command -v eslint >/dev/null 2>&1; then eslint . || { echo \"❌ ESLint issues found.\"; exit 1; }; else echo \"  ⚠ eslint not installed, skipping lint\"; fi"
            .into(),
    );
    lines.push(String::new());
}

fn gen_python_hook(_cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    lines.push("echo \"🔍 Checking formatting with ruff...\"".into());
    lines.push(
        "if command -v ruff >/dev/null 2>&1; then ruff format --check . || { echo \"❌ Formatting issues found. Run 'ruff format .' to fix.\"; exit 1; }; else echo \"  ⚠ ruff not installed, skipping format check\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push("echo \"🔍 Running ruff check...\"".into());
    lines.push(
        "if command -v ruff >/dev/null 2>&1; then ruff check . || { echo \"❌ Ruff lint issues found.\"; exit 1; }; else echo \"  ⚠ ruff not installed, skipping lint\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push("echo \"🔍 Running mypy...\"".into());
    lines.push(
        "if command -v mypy >/dev/null 2>&1; then mypy . || { echo \"❌ Mypy type issues found.\"; exit 1; }; else echo \"  ⚠ mypy not installed, skipping type check\"; fi"
            .into(),
    );
    lines.push(String::new());
}

fn gen_go_hook(_cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    lines.push("echo \"🔍 Checking formatting with gofmt...\"".into());
    lines.push(
        "if command -v gofmt >/dev/null 2>&1; then [ -z \"$(gofmt -l .)\" ] || { echo \"❌ Formatting issues found. Run 'gofmt -s -w .' to fix.\"; exit 1; }; else echo \"  ⚠ gofmt not installed, skipping format check\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push("echo \"🔍 Running go vet...\"".into());
    lines.push(
        "if command -v go >/dev/null 2>&1; then go vet ./... || { echo \"❌ Go vet issues found.\"; exit 1; }; else echo \"  ⚠ go not installed, skipping vet\"; fi"
            .into(),
    );
    lines.push(String::new());
}

fn gen_java_hook(cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    let tool = match cfg.backend.as_str() {
        "gradle" => "gradle",
        _ => "mvn",
    };
    let lint_cmd = match tool {
        "gradle" => "gradle check",
        _ => "mvn checkstyle:check",
    };

    lines.push("echo \"🔍 Checking formatting with google-java-format...\"".into());
    lines.push(
        "if command -v google-java-format >/dev/null 2>&1; then google-java-format --dry-run . || { echo \"❌ Formatting issues found.\"; exit 1; }; else echo \"  ⚠ google-java-format not installed, skipping format check\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push(format!("echo \"🔍 Running {tool} check...\""));
    lines.push(format!(
        "{lint_cmd} || {{ echo \"❌ {tool} check issues found.\"; exit 1; }}"
    ));
    lines.push(String::new());
}

fn gen_frontend_hook(_cfg: &PrecommitConfig, lines: &mut Vec<String>) {
    lines.push("echo \"🔍 Checking formatting with prettier...\"".into());
    lines.push(
        "if command -v prettier >/dev/null 2>&1; then prettier --check '**/*.{css,html}' || { echo \"❌ Formatting issues found.\"; exit 1; }; else echo \"  ⚠ prettier not installed, skipping format check\"; fi"
            .into(),
    );
    lines.push(String::new());

    lines.push("echo \"🔍 Running stylelint...\"".into());
    lines.push(
        "if command -v stylelint >/dev/null 2>&1; then stylelint '**/*.css' || { echo \"❌ Stylelint issues found.\"; exit 1; }; else echo \"  ⚠ stylelint not installed, skipping lint\"; fi"
            .into(),
    );
    lines.push(String::new());
}

/// Install a pre-commit hook in the git repository at `repo_path`.
pub fn install_precommit(repo_path: &Path, cfg: &PrecommitConfig) -> ToolResult<()> {
    let hooks = hooks_dir(repo_path);
    if !hooks.exists() {
        return Err(ToolError::Generic(format!(
            "Not a git repository (no .git/hooks directory found at {})",
            hooks.display()
        )));
    }

    let hook_path = hooks.join(HOOK_NAME);
    if hook_path.exists() {
        return Err(ToolError::Generic(format!(
            "A pre-commit hook already exists at {}. Use `sisyphus precommit uninstall` first, or remove it manually.",
            hook_path.display()
        )));
    }

    let script = generate_hook_script(cfg);
    std::fs::write(&hook_path, script.as_bytes())?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let metadata = std::fs::metadata(&hook_path)?;
        let mut perms = metadata.permissions();
        let mode = perms.mode();
        perms.set_mode(mode | 0o111);
        std::fs::set_permissions(&hook_path, perms)?;
    }

    Ok(())
}

/// Uninstall the pre-commit hook.
pub fn uninstall_precommit(repo_path: &Path) -> ToolResult<()> {
    let hook_path = hooks_dir(repo_path).join(HOOK_NAME);
    if !hook_path.exists() {
        return Err(ToolError::Generic(format!(
            "No pre-commit hook found at {}",
            hook_path.display()
        )));
    }
    std::fs::remove_file(&hook_path)?;
    Ok(())
}

/// Check if a pre-commit hook is installed.
pub fn has_precommit(repo_path: &Path) -> bool {
    hooks_dir(repo_path).join(HOOK_NAME).exists()
}

/// Read the current pre-commit hook content, if it exists.
pub fn read_precommit(repo_path: &Path) -> Option<String> {
    let path = hooks_dir(repo_path).join(HOOK_NAME);
    if path.exists() {
        std::fs::read_to_string(&path).ok()
    } else {
        None
    }
}

/// Check whether the installed hook was generated by Sisyphus.
pub fn is_sisyphus_hook(repo_path: &Path) -> bool {
    read_precommit(repo_path).is_some_and(|content| content.contains("Sisyphus pre-commit hook"))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[cfg(unix)]
    use std::os::unix::fs::PermissionsExt;
    use std::path::PathBuf;
    use tempfile::TempDir;

    fn init_git_repo(dir: &Path) {
        let hooks = dir.join(".git").join("hooks");
        std::fs::create_dir_all(&hooks).unwrap();
        std::fs::write(
            dir.join(".git").join("config"),
            b"[core]\n\trepositoryformatversion = 0\n",
        )
        .unwrap();
    }

    #[test]
    fn test_generate_hook_script_default() {
        let cfg = PrecommitConfig::default();
        let script = generate_hook_script(&cfg);

        assert!(script.contains("cargo fmt --check"));
        assert!(script.contains("cargo clippy -- -D warnings"));
        assert!(script.contains("Sisyphus pre-commit hook"));
        assert!(script.starts_with("#!/bin/sh"));
        assert!(script.ends_with('\n'));
    }

    #[test]
    fn test_generate_hook_script_no_fmt() {
        let cfg = PrecommitConfig {
            check_fmt: false,
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(!script.contains("cargo fmt"));
        assert!(script.contains("cargo clippy"));
    }

    #[test]
    fn test_generate_hook_script_no_clippy_deny() {
        let cfg = PrecommitConfig {
            lint_deny_warnings: false,
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("cargo fmt --check"));
        assert!(script.contains("cargo clippy"));
        assert!(!script.contains("cargo clippy -- -D warnings"));
    }

    #[test]
    fn test_generate_hook_node() {
        let cfg = PrecommitConfig {
            backend: "node".into(),
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("prettier"));
        assert!(script.contains("eslint"));
        assert!(!script.contains("cargo"));
    }

    #[test]
    fn test_generate_hook_python() {
        let cfg = PrecommitConfig {
            backend: "python".into(),
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("ruff format"));
        assert!(script.contains("ruff check"));
        assert!(script.contains("mypy"));
        assert!(!script.contains("cargo"));
    }

    #[test]
    fn test_generate_hook_go() {
        let cfg = PrecommitConfig {
            backend: "go".into(),
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("gofmt"));
        assert!(script.contains("go vet"));
        assert!(!script.contains("cargo"));
    }

    #[test]
    fn test_generate_hook_java() {
        let cfg = PrecommitConfig {
            backend: "java".into(),
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("google-java-format"));
        assert!(script.contains("mvn checkstyle"));
        assert!(!script.contains("cargo"));
    }

    #[test]
    fn test_generate_hook_frontend() {
        let cfg = PrecommitConfig {
            backend: "fe".into(),
            ..Default::default()
        };
        let script = generate_hook_script(&cfg);
        assert!(script.contains("prettier"));
        assert!(script.contains("stylelint"));
        assert!(!script.contains("cargo"));
    }

    #[test]
    fn test_install_and_has_precommit() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        let cfg = PrecommitConfig::default();
        assert!(!has_precommit(dir.path()));

        install_precommit(dir.path(), &cfg).unwrap();
        assert!(has_precommit(dir.path()));

        let installed = std::fs::read_to_string(dir.path().join(".git/hooks/pre-commit")).unwrap();
        assert!(installed.contains("Sisyphus pre-commit hook"));

        #[cfg(unix)]
        {
            let metadata = std::fs::metadata(dir.path().join(".git/hooks/pre-commit")).unwrap();
            assert!(metadata.permissions().mode() & 0o111 != 0);
        }
    }

    #[test]
    fn test_install_on_non_git_dir_returns_error() {
        let dir = TempDir::new().unwrap();
        let result = install_precommit(dir.path(), &PrecommitConfig::default());
        assert!(result.is_err());
        assert!(result
            .unwrap_err()
            .to_string()
            .contains("Not a git repository"));
    }

    #[test]
    fn test_install_twice_returns_error() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        install_precommit(dir.path(), &PrecommitConfig::default()).unwrap();
        let result = install_precommit(dir.path(), &PrecommitConfig::default());
        assert!(result.is_err());
        assert!(result.unwrap_err().to_string().contains("already exists"));
    }

    #[test]
    fn test_uninstall() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        install_precommit(dir.path(), &PrecommitConfig::default()).unwrap();
        assert!(has_precommit(dir.path()));

        uninstall_precommit(dir.path()).unwrap();
        assert!(!has_precommit(dir.path()));
    }

    #[test]
    fn test_uninstall_nonexistent_returns_error() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        let result = uninstall_precommit(dir.path());
        assert!(result.is_err());
        assert!(result
            .unwrap_err()
            .to_string()
            .contains("No pre-commit hook found"));
    }

    #[test]
    fn test_is_sisyphus_hook() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        assert!(!is_sisyphus_hook(dir.path()));

        install_precommit(dir.path(), &PrecommitConfig::default()).unwrap();
        assert!(is_sisyphus_hook(dir.path()));

        std::fs::write(
            dir.path().join(".git/hooks/pre-commit"),
            "#!/bin/sh\necho \"custom hook\"\n",
        )
        .unwrap();
        assert!(!is_sisyphus_hook(dir.path()));
    }

    #[test]
    fn test_read_precommit() {
        let dir = TempDir::new().unwrap();
        init_git_repo(dir.path());

        assert!(read_precommit(dir.path()).is_none());

        install_precommit(dir.path(), &PrecommitConfig::default()).unwrap();
        let content = read_precommit(dir.path());
        assert!(content.is_some());
        assert!(content.unwrap().contains("Sisyphus pre-commit hook"));
    }
}
